effect.shader:
vec2 u_xlat0;
bvec2 u_xlatb0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
vec3 u_xlat8;
vec2 u_xlat13;
bvec2 u_xlatb13;
vec2 u_xlat14;
bvec2 u_xlatb14;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.x = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat0.x = sqrt(u_xlat0.x);
    u_xlat6.xy = vec2(_separate, _direction) * vec2(0.0500000007, 0.0174532942);
    u_xlat1.x = sin(u_xlat6.y);
    u_xlat2.x = cos(u_xlat6.y);
    u_xlat2.x = u_xlat6.x * u_xlat2.x;
    u_xlat2.y = u_xlat6.x * u_xlat1.x;
    u_xlat6.xy = u_xlat2.xy + acScreenNorm.xy;
    u_xlatb1.xy = lessThan(u_xlat6.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb13.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat6.xyxy).xy;
    u_xlat14.xy = fract(u_xlat6.xy);
    u_xlat14.xy = (-u_xlat14.xy) + vec2(1.0, 1.0);
    u_xlat13.x = (u_xlatb13.x) ? u_xlat14.x : u_xlat6.x;
    u_xlat13.y = (u_xlatb13.y) ? u_xlat14.y : u_xlat6.y;
    {
        vec3 hlslcc_movcTemp = u_xlat6;
        hlslcc_movcTemp.x = (u_xlatb1.x) ? (-u_xlat6.x) : u_xlat13.x;
        hlslcc_movcTemp.y = (u_xlatb1.y) ? (-u_xlat6.y) : u_xlat13.y;
        u_xlat6 = hlslcc_movcTemp;
    }
    u_xlat1 = texture(inputImg, u_xlat6.xy);
    u_xlat3 = texture(inputImg, acScreenNorm.xy);
    u_xlat6.xy = (-u_xlat2.xy) + acScreenNorm.xy;
    u_xlatb2.xy = lessThan(u_xlat6.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb14.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat6.xyxy).xy;
    u_xlat4.xy = fract(u_xlat6.xy);
    u_xlat4.xy = (-u_xlat4.xy) + vec2(1.0, 1.0);
    u_xlat14.x = (u_xlatb14.x) ? u_xlat4.x : u_xlat6.x;
    u_xlat14.y = (u_xlatb14.y) ? u_xlat4.y : u_xlat6.y;
    {
        vec3 hlslcc_movcTemp = u_xlat6;
        hlslcc_movcTemp.x = (u_xlatb2.x) ? (-u_xlat6.x) : u_xlat14.x;
        hlslcc_movcTemp.y = (u_xlatb2.y) ? (-u_xlat6.y) : u_xlat14.y;
        u_xlat6 = hlslcc_movcTemp;
    }
    u_xlat2 = texture(inputImg, u_xlat6.xy);
    u_xlat4.x = dot(u_xlat1.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat4.y = dot(u_xlat3.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat4.z = dot(u_xlat2.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat2.x = u_xlat1.x;
    u_xlat2.y = u_xlat3.y;
    u_xlat6.xyz = (-u_xlat2.xyz) + u_xlat4.xyz;
    u_xlat6.xyz = vec3(vec3(_black_white, _black_white, _black_white)) * u_xlat6.xyz + u_xlat2.xyz;
    u_xlat1.x = max(u_xlat1.w, u_xlat3.w);
    u_xlat1.w = max(u_xlat2.w, u_xlat1.x);
    u_xlatb2.x = int(_scanline)==1;
    u_xlat8.x = acScreenNorm.y * 800.0;
    u_xlat8.x = sin(u_xlat8.x);
    u_xlat8.xyz = (-u_xlat8.xxx) * vec3(0.0399999991, 0.0399999991, 0.0399999991) + u_xlat6.xyz;
    u_xlat8.xyz = u_xlat1.www * u_xlat8.xyz;
    u_xlat6.xyz = (u_xlatb2.x) ? u_xlat8.xyz : u_xlat6.xyz;
    u_xlatb2.x = int(_vignette)==1;
    u_xlat0.x = (-u_xlat0.x) * 0.5 + 1.0;
    u_xlat8.xyz = u_xlat0.xxx * u_xlat6.xyz;
    u_xlat1.xyz = (u_xlatb2.x) ? u_xlat8.xyz : u_xlat6.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlatb0.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat2 = (u_xlatb0.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat3 = u_xlat3 * u_xlat5;
        u_xlat2 = u_xlat2 * u_xlat4 + u_xlat3;
        u_xlat0.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb0.y) ? u_xlat0.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
